def distinct_prime_factors(n):
    n = abs(n)
    factors = []
    d = 2
    while d * d <= n:
        if n % d == 0:
            factors.append(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def sentence_case_keep_i(s):
    lowered = s.lower()
    words = lowered.split(" ")
    words = ["I" if w == "i" else w for w in words]
    joined = " ".join(words)
    for i, ch in enumerate(joined):
        if ch.isalpha():
            return joined[:i] + ch.upper() + joined[i + 1:]
    return joined

def remove_first_and_last_occurrence(s, ch):
    first = s.find(ch)
    if first == -1:
        return s
    last = s.rfind(ch)
    if first == last:
        return s[:first] + s[first + 1:]
    chars = list(s)
    del chars[last]
    del chars[first]
    return "".join(chars)

def integer_cube_root(n):
    if n == 0:
        return 0
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid ** 3 <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

