def smart_truncate(s, maxlen):
    if len(s) <= maxlen:
        return s
    limit = maxlen - 3
    if limit <= 0:
        return s[:maxlen]
    truncated = s[:limit]
    if ' ' in truncated:
        truncated = truncated[:truncated.rfind(' ')]
    return truncated + '...'
